# 2026-09-17 … 各フォルダの目次ファイル（00_このフォルダにあるもの.md）は作らない。
# 定数は「作らない対象の名前」として、削除チェックのためだけに残す。
INDEX_NAME = "00_このフォルダにあるもの.md"


def title(no):
    return RENAME.get(no, rows[no]["item"].replace(" ", ""))


def fname(no):
    return title(no) + ".md"


def link(text, path):
    return f"[{text}]({urllib.parse.quote(path)})"


def write(path, text):
    p = ROOT / path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text.lstrip("\n"), encoding="utf-8")


# ---- 検証 ----------------------------------------------------------
allno = sorted(n for _, _, ns in THEMES for n in ns)
assert allno == list(range(1, 134)), "割り当て漏れ/重複"
names = [fname(n) for n in range(1, 134)]
assert len(set(names)) == 133, [n for n in names if names.count(n) > 1]
for n in names:
    assert not any(c in n for c in '/\\:*?"<>|()'), n

theme_of = {n: t for t, _, ns in THEMES for n in ns}
PH = {"Phase1 コア": "Phase1", "Phase2 設計構築": "Phase2",
      "Phase3 専門": "Phase3", "Phase4 網羅": "Phase4"}

