def note_items(entry):
    """ノートの定義から (ファイル名, 説明, 完全に扱う項目, 一部だけ扱う項目) を返す。

    既存の 3 要素タプルと、一部カバーを表す 4 要素タプルの両方を受け付ける。
    """
    f, desc, full = entry[0], entry[1], entry[2]
    part = entry[3] if len(entry) > 3 else []
    return f, desc, full, part


WRITTEN = {n for lst in NOTES.values() for e in lst for n in note_items(e)[2]}

